# Complete remaining routes on a 0.05 mm search grid; all resulting copper must
# subsequently pass tscircuit checks. The bottom ground pour is regenerated by
# tscircuit, so each isolated ground pad only needs an escape to the bottom layer.
# Dependencies: numpy, scipy, shapely. Run after route-hub.ts / import-hub-routes.ts.
import json,math,heapq,time,os
import numpy as np
import shapely
from shapely.geometry import Point,LineString,Polygon,box
from shapely.ops import unary_union
from shapely.affinity import rotate
from scipy.ndimage import distance_transform_edt
base=json.load(open('output/hub.unrouted.json'));cache=json.load(open('hub-routes.json'));netmap=json.load(open('output/hub.net-map.json'))
parent={}
def root(x):
 while x in parent:x=parent[x]
 return x
for t in base:
 if t['type']=='source_trace':
  xs=t['connected_source_port_ids']+t['connected_source_net_ids']
  for x in xs[1:]:
   a,b=root(xs[0]),root(x)
   if a!=b:parent[b]=a
names={root(e['source_net_id']):e['name'] for e in base if e['type']=='source_net'}
sts={e['source_trace_id']:e for e in base if e['type']=='source_trace'}
pp={e['pcb_port_id']:e for e in base if e['type']=='pcb_port'}
manual=[e for e in base if e['type']=='pcb_trace']
# A primitive is (net, layer, polygon, kind, port id).
pads=[];vertical=[];portxy={}
for p in base:
 if p['type'] not in ['pcb_smtpad','pcb_plated_hole']:continue
 port=pp[p['pcb_port_id']];net=names.get(root(port['source_port_id']),port['source_port_id']);x,y=p.get('x'),p.get('y')
 if p['shape']=='polygon':shape=Polygon([(q['x'],q['y']) for q in p['points']])
 else:
  w=p.get('width',p.get('outer_width',p.get('radius',0)*2));h=p.get('height',p.get('outer_height',p.get('radius',0)*2))
  shape=box(x-w/2,y-h/2,x+w/2,y+h/2)
  if p.get('ccw_rotation'):shape=rotate(shape,p['ccw_rotation'],origin=(x,y))
 layers=[0,1] if p['type']=='pcb_plated_hole' else [0 if p['layer']=='top' else 1]
 for l in layers:pads.append((net,l,shape,'pad',port['source_port_id']))
 portxy[port['source_port_id']]=(port['x'],port['y'])
 if len(layers)==2:vertical.append((net,port['x'],port['y']))
fixed=[]
for e in base:
 if e['type']=='pcb_keepout':
  x,y=e['center']['x'],e['center']['y'];r=e['radius'];fixed.append((box(x-r,y-r,x+r,y+r),.161))
 if e['type']=='pcb_hole':
  x,y=e.get('x',e.get('center',{}).get('x')),e.get('y',e.get('center',{}).get('y'));fixed.append((Point(x,y).buffer(e['hole_diameter']/2),.201))
# Reserve a short escape corridor at fine-pitch IC pins, so completing one net
# cannot seal a neighboring, not-yet-routed pin into a pocket.
escapes=[]
components={e['source_component_id']:e for e in base if e['type']=='source_component'}
pcs={e['source_component_id']:e for e in base if e['type']=='pcb_component'}
sourceports={e['source_port_id']:e for e in base if e['type']=='source_port'}
for p in pp.values():
 sp=sourceports[p['source_port_id']];part=components[sp['source_component_id']];name=part['name']
 if name not in ['U1','U2','U3','U4','U7','U10','U13']:continue
 net=names.get(root(p['source_port_id']))
 if not net:continue
 pc=pcs[sp['source_component_id']];center=pc.get('footprint_origin',pc['center']);dx=p['x']-center['x'];dy=p['y']-center['y']
 if max(abs(dx),abs(dy))<.5:continue
 length=.9 if name=='U1' else .6
 ex,ey=(p['x']+math.copysign(length,dx),p['y']) if abs(dx)>abs(dy) else (p['x'],p['y']+math.copysign(length,dy))
